import type { TypedSchema } from 'vee-validate'
import type { Ref } from 'vue'
import type * as z from 'zod'
import type { Dependency, EnumValues } from './interface'
import { createContext } from 'reka-ui'
import { useFieldValue, useFormValues } from 'vee-validate'
import { computed, ref, watch } from 'vue'
import { DependencyType } from './interface'
import { getFromPath, getIndexIfArray, normalizeFormPath } from './utils'

export const [injectDependencies, provideDependencies] = createContext<Ref<Dependency<z.infer<z.ZodObject<any>>>[] | undefined>>('AutoFormDependencies')

// ---- #2/#14: REQUIRES dependencies must also drive validation ----
//
// `useDependencies` below only ever affects rendering: `isRequired` feeds the
// visual asterisk on the field label, but the vee-validate validation schema
// never learns about it, so a schema-optional field left empty submits fine
// even while a REQUIRES dependency targeting it is active. The functions in
// this section derive the same "is this REQUIRES dependency active, and is
// its target empty" semantics as pure functions of a candidate `values`
// object (no watchers, no reactive schema rebuilding), so `AutoForm.vue` can
// layer them onto the vee-validate typed schema's `parse()` step. Keeping
// this here (rather than in AutoForm.vue) means both the live-render path
// (the `watch` below) and the validation path share one definition of
// "empty" and one definition of "which value pairs a dependency applies to".
// See NOTES in the phase-2 commit for why a `schema.superRefine()` wrapper
// (applied before `toTypedSchema`) was tried first and rejected.

/**
 * Mirrors how zod treats a missing required field: `undefined`, `null`, `''`
 * and `[]` are empty. `false` and `0` are valid, present values and must NOT
 * be flagged.
 */
function isEmptyDependencyValue(value: unknown): boolean {
  if (value === undefined || value === null)
    return true
  if (typeof value === 'string')
    return value.length === 0
  if (Array.isArray(value))
    return value.length === 0
  return false
}

/**
 * Walks `segments` off `base`, expanding into every element whenever an
 * array is encountered along the way — so a schema-level path like
 * `items.hasX` resolves against every `items[N].hasX`.
 *
 * The array check has to come *before* the "ran out of segments" check:
 * for `items.hasX`/`items.x` the shared parent is just `items`, so the last
 * segment is consumed on the way in and we arrive at the array itself with
 * nothing left to walk. Testing `segments.length === 0` first would return
 * the whole array as a single "item", which reads `hasX`/`x` off the array
 * object (always `undefined`) and yields the unmappable path `items.x`
 * instead of one `items[N].x` per element.
 */
function expandDependencyPath(
  base: unknown,
  segments: string[],
  path: (string | number)[] = [],
): { path: (string | number)[], value: unknown }[] {
  if (Array.isArray(base))
    return base.flatMap((item, index) => expandDependencyPath(item, segments, [...path, index]))

  if (segments.length === 0)
    return [{ path, value: base }]

  if (base === null || base === undefined || typeof base !== 'object')
    return []

  const [head, ...rest] = segments
  return expandDependencyPath((base as Record<string, unknown>)[head], rest, [...path, head])
}

interface ResolvedDependencyTarget {
  targetPath: (string | number)[]
  sourceValue: unknown
  targetValue: unknown
}

/**
 * Resolves the (source value, target value, target path) triples a
 * dependency applies to for a given candidate `values` object. Mirrors
 * `getSourceValue()` below: when `sourceField` and `targetField` share the
 * same parent path (e.g. array-item siblings `items.hasX` / `items.x`) they
 * are resolved together, per-item; otherwise both are read directly off the
 * root `values`.
 */
function resolveDependencyTargets(values: Record<string, unknown>, dep: Dependency<any>): ResolvedDependencyTarget[] {
  const sourceSegments = String(dep.sourceField).split('.')
  const targetSegments = String(dep.targetField).split('.')
  const sourceParent = sourceSegments.slice(0, -1).join('.')
  const targetParent = targetSegments.slice(0, -1).join('.')
  const sourceLast = sourceSegments[sourceSegments.length - 1]
  const targetLast = targetSegments[targetSegments.length - 1]

  if (sourceParent && sourceParent === targetParent) {
    return expandDependencyPath(values, sourceParent.split('.')).map(({ path, value: base }) => ({
      targetPath: [...path, targetLast],
      sourceValue: getFromPath(base as Record<string, unknown>, sourceLast),
      targetValue: getFromPath(base as Record<string, unknown>, targetLast),
    }))
  }

  return [{
    targetPath: targetSegments,
    sourceValue: getFromPath(values, String(dep.sourceField)),
    targetValue: getFromPath(values, String(dep.targetField)),
  }]
}

/**
 * Pure function: given a candidate form `values` object and the dependency
 * list, returns the validation issues an active-and-empty REQUIRES
 * dependency should raise. Exported for direct unit testing.
 */
export function getRequiresDependencyIssues(
  values: Record<string, unknown>,
  dependencies: Dependency<any>[] | undefined,
): { path: string, message: string }[] {
  if (!dependencies?.length)
    return []

  const issues: { path: string, message: string }[] = []

  dependencies.forEach((dep) => {
    if (dep.type !== DependencyType.REQUIRES)
      return

    resolveDependencyTargets(values, dep).forEach(({ targetPath, sourceValue, targetValue }) => {
      if (dep.when(sourceValue, targetValue) && isEmptyDependencyValue(targetValue)) {
        issues.push({
          path: normalizeFormPath(targetPath.map(String).join('.')),
          message: 'Required',
        })
      }
    })
  })

  return issues
}

/**
 * Wraps a vee-validate typed schema so its `parse()` step also raises the
 * issues from `getRequiresDependencyIssues`, without touching `cast()` /
 * `describe()`. Those must keep reading the original, unwrapped typed schema
 * so default-value extraction (`resolveInitialValues` in vee-validate core,
 * which falls back to `getDefaults()` in @vee-validate/zod when `.parse()`
 * throws) is unaffected by dependency-driven issues.
 */
export function withDependencyValidation<TInput, TOutput>(
  typedSchema: TypedSchema<TInput, TOutput>,
  dependencies: Dependency<any>[] | undefined,
): TypedSchema<TInput, TOutput> {
  if (!dependencies?.some(dep => dep.type === DependencyType.REQUIRES))
    return typedSchema

  return {
    ...typedSchema,
    async parse(values, context) {
      const base = await typedSchema.parse(values, context)
      const dependencyIssues = getRequiresDependencyIssues(values as Record<string, unknown>, dependencies)
      if (!dependencyIssues.length)
        return base

      const errors = base.errors.map(error => ({ ...error, errors: [...error.errors] }))
      dependencyIssues.forEach(({ path, message }) => {
        const existing = errors.find(error => error.path === path)
        if (existing)
          existing.errors.push(message)
        else
          errors.push({ path, errors: [message] })
      })

      return { value: base.value, errors }
    },
  }
}

export default function useDependencies(
  fieldName: string,
) {
  const form = useFormValues()
  // parsed test[0].age => test.age
  const currentFieldName = fieldName.replace(/\[\d+\]/g, '')
  const currentFieldValue = useFieldValue<any>(fieldName)

  if (!form)
    throw new Error('useDependencies should be used within <AutoForm>')

  const dependencies = injectDependencies()
  const isDisabled = ref(false)
  const isHidden = ref(false)
  const isRequired = ref(false)
  const overrideOptions = ref<EnumValues | undefined>()

  const currentFieldDependencies = computed(() => dependencies.value?.filter(
    dependency => dependency.targetField === currentFieldName,
  ))

  function getSourceValue(dep: Dependency<any>) {
    const source = dep.sourceField as string
    const index = getIndexIfArray(fieldName) ?? -1
    const [sourceLast, ...sourceInitial] = source.split('.').reverse()
    const [_targetLast, ...targetInitial] = (dep.targetField as string).split('.').reverse()

    if (index >= 0 && sourceInitial.join(',') === targetInitial.join(',')) {
      const [_currentLast, ...currentInitial] = fieldName.split('.').reverse()
      return getFromPath(form.value, currentInitial.join('.') + sourceLast)
    }

    return getFromPath(form.value, source)
  }

  const sourceFieldValues = computed(() => currentFieldDependencies.value?.map(dep => getSourceValue(dep)))

  const resetConditionState = () => {
    isDisabled.value = false
    isHidden.value = false
    isRequired.value = false
    overrideOptions.value = undefined
  }

  watch([sourceFieldValues, dependencies], () => {
    resetConditionState()
    currentFieldDependencies.value?.forEach((dep) => {
      const sourceValue = getSourceValue(dep)
      const conditionMet = dep.when(sourceValue, currentFieldValue.value)

      switch (dep.type) {
        case DependencyType.DISABLES:
          if (conditionMet)
            isDisabled.value = true

          break
        case DependencyType.REQUIRES:
          if (conditionMet)
            isRequired.value = true

          break
        case DependencyType.HIDES:
          if (conditionMet)
            isHidden.value = true

          break
        case DependencyType.SETS_OPTIONS:
          if (conditionMet)
            overrideOptions.value = dep.options

          break
      }
    })
  }, { immediate: true, deep: true })

  return {
    isDisabled,
    isHidden,
    isRequired,
    overrideOptions,
  }
}

import type { z } from 'zod'
import type { Shape } from './interface'

// TODO: This should support recursive ZodEffects but TypeScript doesn't allow circular type definitions.
export type ZodObjectOrWrapped =
  | z.ZodObject<any, any>
  | z.ZodEffects<z.ZodObject<any, any>>

/**
 * Beautify a camelCase string.
 * e.g. "myString" -> "My String"
 */
export function beautifyObjectName(string: string) {
  // Remove bracketed indices
  // if numbers only return the string
  let output = string.replace(/\[\d+\]/g, '').replace(/([A-Z])/g, ' $1')
  output = output.charAt(0).toUpperCase() + output.slice(1)
  return output
}

/**
 * Parse string and extract the index
 * @param string
 * @returns index or undefined
 */
export function getIndexIfArray(string: string) {
  const indexRegex = /\[(\d+)\]/
  // Match the index
  const match = string.match(indexRegex)
  // Extract the index (number)
  const index = match ? Number.parseInt(match[1]) : undefined
  return index
}

/**
 * Get the lowest level Zod type.
 * This will unpack optionals, refinements, etc.
 */
export function getBaseSchema<
  ChildType extends z.ZodAny | z.AnyZodObject = z.ZodAny,
>(schema: ChildType | z.ZodEffects<ChildType>): ChildType | null {
  if (!schema)
    return null
  if ('innerType' in schema._def)
    return getBaseSchema(schema._def.innerType as ChildType)

  if ('schema' in schema._def)
    return getBaseSchema(schema._def.schema as ChildType)

  return schema as ChildType
}

/**
 * Get the type name of the lowest level Zod type.
 * This will unpack optionals, refinements, etc.
 */
export function getBaseType(schema: z.ZodAny) {
  const baseSchema = getBaseSchema(schema)
  return baseSchema ? baseSchema._def.typeName : ''
}

/**
 * Search for a "ZodDefault" in the Zod stack and return its value.
 */
export function getDefaultValueInZodStack(schema: z.ZodAny): any {
  const typedSchema = schema as unknown as z.ZodDefault<
    z.ZodNumber | z.ZodString
  >

  if (typedSchema._def.typeName === 'ZodDefault')
    return typedSchema._def.defaultValue()

  if ('innerType' in typedSchema._def) {
    return getDefaultValueInZodStack(
      typedSchema._def.innerType as unknown as z.ZodAny,
    )
  }
  if ('schema' in typedSchema._def) {
    return getDefaultValueInZodStack(
      (typedSchema._def as any).schema as z.ZodAny,
    )
  }

  return undefined
}

/**
 * Search the Zod wrapper stack (optionals, defaults, effects, etc.) for a
 * `ZodReadonly` at any depth. Unlike `getBaseSchema`, this does not stop at
 * the first unwrap — it walks the whole stack, since `.readonly()` can be
 * layered anywhere (e.g. `z.string().readonly()` or
 * `z.string().optional().readonly()`).
 */
export function isReadonlyInZodStack(schema: z.ZodAny): boolean {
  if (!schema)
    return false

  const typedSchema = schema as unknown as z.ZodTypeAny

  if (typedSchema._def.typeName === 'ZodReadonly')
    return true

  if ('innerType' in typedSchema._def) {
    return isReadonlyInZodStack(
      typedSchema._def.innerType as unknown as z.ZodAny,
    )
  }
  if ('schema' in typedSchema._def) {
    return isReadonlyInZodStack(
      (typedSchema._def as any).schema as z.ZodAny,
    )
  }

  return false
}

/**
 * Phase 4C (#11): a `ZodUnion` field used to render nothing — `getBaseSchema`
 * stops at `ZodUnion` (it only unwraps wrappers that carry an `innerType` or
 * `schema` in `_def`), so `getBaseType` yielded `'ZodUnion'`, which has no
 * `DEFAULT_ZOD_HANDLERS` entry. Validation must stay against the *full*
 * union (the consumer's schema still enforces every member — e.g.
 * `z.union([z.literal(''), z.string().email().optional()])` must keep
 * accepting both `''` and a valid email), but *rendering* has to commit to
 * one shape.
 *
 * This picks the first union member that isn't just a literal/undefined/null
 * placeholder (those carry no renderable "type" of their own — e.g. the
 * `z.literal('')` escape hatch in the case above) and unwraps *that
 * member's own* wrapper stack (optional, nullable, effects, etc.) via
 * `getBaseSchema`. Falls back to the first member (also unwrapped) if every
 * member is a literal/undefined/null.
 */
export function resolveUnionRenderSchema(schema: z.ZodUnion<[z.ZodTypeAny, ...z.ZodTypeAny[]]>): z.ZodAny {
  const members = schema._def.options as z.ZodAny[]
  const isPlaceholder = (member: z.ZodAny) => {
    const typeName = getBaseSchema(member)?._def.typeName
    return typeName === 'ZodLiteral' || typeName === 'ZodUndefined' || typeName === 'ZodNull'
  }
  const renderMember = members.find(member => !isPlaceholder(member)) ?? members[0]
  return getBaseSchema(renderMember) ?? renderMember
}

/**
 * The schema a field should *render* as: the unwrapped base schema, except
 * for a `ZodUnion`, which commits to one member (see
 * `resolveUnionRenderSchema`). Validation always stays against the original,
 * fully-wrapped schema — this only decides which component gets picked.
 */
export function getRenderSchema(schema: z.ZodAny): z.ZodAny | null {
  const baseSchema = getBaseSchema(schema)
  if (baseSchema && baseSchema._def.typeName === 'ZodUnion')
    return resolveUnionRenderSchema(baseSchema as any)
  return baseSchema
}

/**
 * Enum options off a render schema. `ZodEnum` carries an array in
 * `_def.values`; `ZodNativeEnum` carries an object map that needs
 * `Object.values()`.
 */
export function getSchemaOptions(renderSchema: z.ZodAny | null | undefined): string[] | undefined {
  const values = (renderSchema && 'values' in renderSchema._def) ? renderSchema._def.values as string[] : undefined
  if (values && !Array.isArray(values) && typeof values === 'object')
    return Object.values(values)
  return values
}

/**
 * Builds the `Shape` descriptor `AutoFormField` dispatches on, for one entry
 * of a `ZodObject`'s shape. Returns `null` for a `.readonly()` field, which
 * must render nothing at all rather than an editable control (#12).
 *
 * Shared by `AutoForm.vue` and `AutoFormFieldObject.vue` so that readonly
 * skipping, union rendering (#11) and enum option extraction (#3) behave
 * identically at every nesting level — they previously drifted because each
 * component hand-rolled its own copy of this loop body.
 */
export function buildShape(item: z.ZodAny): Shape | null {
  if (isReadonlyInZodStack(item))
    return null

  const renderItem = getRenderSchema(item)

  return {
    type: renderItem ? getBaseType(renderItem) : getBaseType(item),
    default: getDefaultValueInZodStack(item),
    options: getSchemaOptions(renderItem),
    required: !['ZodOptional', 'ZodNullable'].includes(item._def.typeName),
    // The *unwrapped* schema, so that `AutoFormField`'s `shape.schema.description`
    // reads a `.describe()` set on the inner type, and so a wrapped container
    // (e.g. `z.array(...).optional()`) still reaches `AutoFormFieldArray` as a
    // `ZodArray` it can destructure.
    schema: getBaseSchema(item),
  }
}

export function getObjectFormSchema(
  schema: ZodObjectOrWrapped,
): z.ZodObject<any, any> {
  if (schema?._def.typeName === 'ZodEffects') {
    const typedSchema = schema as z.ZodEffects<z.ZodObject<any, any>>
    return getObjectFormSchema(typedSchema._def.schema)
  }
  return schema as z.ZodObject<any, any>
}

function isIndex(value: unknown): value is number {
  return Number(value) >= 0
}
/**
 * Constructs a path with dot paths for arrays to use brackets to be compatible with vee-validate path syntax
 */
export function normalizeFormPath(path: string): string {
  const pathArr = path.split('.')
  if (!pathArr.length)
    return ''

  let fullPath = String(pathArr[0])
  for (let i = 1; i < pathArr.length; i++) {
    if (isIndex(pathArr[i])) {
      fullPath += `[${pathArr[i]}]`
      continue
    }

    fullPath += `.${pathArr[i]}`
  }

  return fullPath
}

type NestedRecord = Record<string, unknown> | { [k: string]: NestedRecord }
/**
 * Checks if the path opted out of nested fields using `[fieldName]` syntax
 */
export function isNotNestedPath(path: string) {
  return /^\[.+\]$/.test(path)
}
function isObject(obj: unknown): obj is Record<string, unknown> {
  return obj !== null && !!obj && typeof obj === 'object' && !Array.isArray(obj)
}
function isContainerValue(value: unknown): value is Record<string, unknown> {
  return isObject(value) || Array.isArray(value)
}
function cleanupNonNestedPath(path: string) {
  if (isNotNestedPath(path))
    return path.replace(/\[|\]/g, '')

  return path
}

/**
 * Gets a nested property value from an object
 */
export function getFromPath<TValue = unknown>(object: NestedRecord | undefined, path: string): TValue | undefined
export function getFromPath<TValue = unknown, TFallback = TValue>(
  object: NestedRecord | undefined,
  path: string,
  fallback?: TFallback,
): TValue | TFallback
export function getFromPath<TValue = unknown, TFallback = TValue>(
  object: NestedRecord | undefined,
  path: string,
  fallback?: TFallback,
): TValue | TFallback | undefined {
  if (!object)
    return fallback

  if (isNotNestedPath(path))
    return object[cleanupNonNestedPath(path)] as TValue | undefined

  const resolvedValue = (path || '')
    .split(/\.|\[(\d+)\]/)
    .filter(Boolean)
    .reduce((acc, propKey) => {
      if (isContainerValue(acc) && propKey in acc)
        return acc[propKey]

      return fallback
    }, object as unknown)

  return resolvedValue as TValue | undefined
}

type Booleanish = boolean | 'true' | 'false'

export function booleanishToBoolean(value: Booleanish) {
  switch (value) {
    case 'true':
    case true:
      return true
    case 'false':
    case false:
      return false
  }
}

/**
 * Narrows an optional `Booleanish` to a `boolean`, preserving the
 * absent/present distinction: only `undefined` yields `undefined`.
 *
 * The test must be `value === undefined`, not `value ?`, because callers use
 * the result as `maybeBooleanishToBoolean(config?.inputProps?.disabled) ??
 * disabled` — a truthiness test collapses an explicit `false` into "not
 * provided", so `inputProps.disabled = false` fell through to the outer
 * `disabled` prop and could never override a dependency-driven disable.
 * (The string `'false'` was unaffected, which is what made the asymmetry
 * easy to miss.)
 */
export function maybeBooleanishToBoolean(value?: Booleanish) {
  return value === undefined ? undefined : booleanishToBoolean(value)
}
